{
  "IP": "neorv32_sysinfo",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Reported clock frequency",
      "Unit": "neorv32_sysinfo",
      "Information": "The current reported clock-frequency value is held in the system-information table, initialized at reset and replaceable by a bus write. The bus consumer depends on it as timing metadata.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is yes because the qualifying bus access at line 94 writes bus_req_i.data into the stored value at line 95 without an additional restriction. Confidentiality is no because the value is timing metadata rather than secret material, although it is returned at line 168. Availability is no because the value does not gate a port or required operation. Undermined Expected Behavior is no because no privileged mode, override, bypass, or test behavior acts on it.",
      "Objectives At Risk": [
        "I"
      ],
      "Attack": "An unauthorized bus master could issue a write satisfying line 94 and place a false frequency through line 95, causing software to use incorrect timing metadata.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        95
      ],
      "Held Lines": [
        92,
        95
      ],
      "Exit Lines": [
        168
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Static system configuration and capability information",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "The sizes, hart count, boot mode, cache parameters, and feature flags are derived only from build-time generics and constants at lines 102-150, so the build-time-values rule excludes them even though line 168 returns them."
    },
    {
      "Candidate Name": "Bus access control, address, and handshake",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "The access fields select or qualify the register access, while buf_ack and buf_adr only repeat or hold that access for the response at lines 160-169; the access-command, bus-handshake-copy, and held-address rules exclude them as independent information."
    },
    {
      "Candidate Name": "Clock and reset timing",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "clk_i and rstn_i only time or reset the table and access-buffer state, so the clock-and-reset exclusion bars them as conceptual assets."
    }
  ],
  "Notes": []
}
